            if state in seen:
                return
            seen.add(state)
            straight = (r + dr, c + dc)
            if straight in walls:
                if degree(straight) < 3 or out[straight[0]][straight[1]] != wall:
                    out[straight[0]][straight[1]] = color
                r, c = straight
                continue
            options = []
            for ndr, ndc in ((-dc, dr), (dc, -dr)):
                q = (r + ndr, c + ndc)
                if q in walls:
                    options.append((q, ndr, ndc))
            if len(options) != 1:
                return
            out[r][c] = color
            (r, c), dr, dc = options[0]
            if degree((r, c)) < 3 or out[r][c] != wall:
                out[r][c] = color

    # Extend the two ends of each source wall through forced turns. Straight
    # connectors at junctions remain unpainted; a forced turn paints the corner.
    for run, dr, dc, color in roots:
        r, c = run[0]
        trace((r, c), -dr, -dc, color)
        r, c = run[-1]
        trace((r, c), dr, dc, color)

    # At a T/cross whose opposite arms are source walls, paint its other arms.
    for run, dr, dc, color in roots:
        for r, c in run:
            if dr == 0:
                opposite = ((r, c - 1) in walls and (r, c + 1) in walls and
                            out[r][c - 1] == color and out[r][c + 1] == color)
                branches = ((-1, 0), (1, 0))
            else:
                opposite = ((r - 1, c) in walls and (r + 1, c) in walls and
                            out[r - 1][c] == color and out[r + 1][c] == color)
                branches = ((0, -1), (0, 1))
            if opposite:
                for ndr, ndc in branches:
                    q = (r + ndr, c + ndc)
                    if q in walls and out[q[0]][q[1]] == wall:
                        trace((r, c), ndr, ndc, color)

    # Small detached bends immediately beside a source belong to that source.
    unseen = set(walls)
    while unseen:
        first = unseen.pop()
        stack, comp = [first], [first]
        while stack:
            r, c = stack.pop()
            for dr, dc in orth:
                q = (r + dr, c + dc)
                q = (r + dr, c + dc)
                if q in unseen:
                    unseen.remove(q)
                    stack.append(q)
                    comp.append(q)
        if any(out[r][c] != wall for r, c in comp):
            continue
        candidates = []
        for r0, r1, c0, c1, color in sources:
            reach = 2 * max(r1 - r0 + 1, c1 - c0 + 1) - 2
            distances = [max(r0 - r, 0, r - r1) + max(c0 - c, 0, c - c1)
                         for r, c in comp]
            if max(distances) <= reach:
                candidates.append((max(distances), color))
        if candidates:
            candidates.sort()
            if len(candidates) == 1 or candidates[0][0] < candidates[1][0]:
                for r, c in comp:
                    out[r][c] = candidates[0][1]
    return out
