def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    wall = Counter(v for row in grid for v in row if v != bg).most_common(1)[0][0]
    orth = ((1, 0), (-1, 0), (0, 1), (0, -1))

    seeds = {(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, wall)}
    source_of = {}
    source_colors = {}
    sid = 0
    while seeds:
        first = seeds.pop()
        stack, cells = [first], [first]
        while stack:
            r, c = stack.pop()
            for dr, dc in orth:
                p = (r + dr, c + dc)
                if p in seeds:
                    seeds.remove(p)
                    stack.append(p)
                    cells.append(p)
        for p in cells:
            source_of[p] = sid
        source_colors[sid] = Counter(grid[r][c] for r, c in cells).most_common(1)[0][0]
        sid += 1

    walls = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == wall}
    def neighbors(p):
        r, c = p
        return [(r + dr, c + dc) for dr, dc in orth if (r + dr, c + dc) in walls]

    degree = {p: len(neighbors(p)) for p in walls}
    nodes = {p for p in walls if degree[p] != 2}
    paths = []
    used = set()
    for start in nodes:
        for nxt in neighbors(start):
            edge = tuple(sorted((start, nxt)))
            if edge in used:
                continue
            used.add(edge)
            path = [start, nxt]
            prev, cur = start, nxt
            while cur not in nodes:
                following = [p for p in neighbors(cur) if p != prev][0]
                used.add(tuple(sorted((cur, following))))
                path.append(following)
                prev, cur = cur, following
            paths.append(path)

    # Degenerate closed loops, if any, are also maximal paths.
    for p in walls:
        for q in neighbors(p):
            edge = tuple(sorted((p, q)))
            if edge in used:
                continue
            path = [p, q]
            used.add(edge)
            prev, cur = p, q
            while cur != p:
                following = [x for x in neighbors(cur) if x != prev]
                if not following:
                    break
                nxt = following[0]
                used.add(tuple(sorted((cur, nxt))))
                path.append(nxt)
                prev, cur = cur, nxt
            paths.append(path)

    owners = [set() for _ in paths]
    for i, path in enumerate(paths):
        adjacent_sources = set()
        for r, c in path:
            if degree[(r, c)] >= 3:
                continue
            for dr, dc in orth:
                p = (r + dr, c + dc)
                if p in source_of:
                    adjacent_sources.add(source_of[p])
        if len(adjacent_sources) == 1:
            owners[i] = adjacent_sources

    incident = {p: [] for p in nodes}
    for i, path in enumerate(paths):
        if path[0] in incident:
            incident[path[0]].append(i)
        if path[-1] in incident and path[-1] != path[0]:
            incident[path[-1]].append(i)

    # Paint short connectors joining walls owned by the same source. Keep track
    # of source identity, not merely its display color: equal-colored patterns
    # can still have uncolored intersections.
    changed = True
    while changed:
        changed = False
        for i, path in enumerate(paths):
            if owners[i]:
                continue
            end_sources = []
            for endpoint in (path[0], path[-1]):
                sources = set()
                for j in incident.get(endpoint, []):
                    if j != i:
                        sources |= owners[j]
                end_sources.append(sources)
            common = end_sources[0] & end_sources[1]
            if len(common) == 1:
                owners[i] = set(common)
                changed = True

    claims = {p: set() for p in walls}
    for path, sources in zip(paths, owners):
        if sources:
            for p in path:
                claims[p] |= sources
    for (r, c), sources in claims.items():
        if len(sources) == 1:
            out[r][c] = source_colors[next(iter(sources))]
    return out
